const generateSeedScans = () => {
  const types = ["Vehicle", "Driver", "Station", "Unknown Tag"];
  const list = [];
  const now = Date.now();
  
  for (let i = 50; i >= 1; i--) {
    const isVerified = i % 8 !== 0; // some unknowns to keep it realistic
    const type = isVerified ? types[i % 3] : "Unknown Tag";
    const status = isVerified ? ("VERIFIED" as const) : ("UNKNOWN" as const);
    
    // Generate static but realistic tags
    let tag = "INVALID-TAG-XYZ";
    if (type === "Vehicle") {
      tag = `MOKA-VEH-${1000 + i * 17}`;
    } else if (type === "Driver") {
      tag = `MOKA-DRV-${2000 + i * 29}`;
    } else if (type === "Station") {
      tag = `MOKA-STA-0${100 + i * 7}`;
    } else {
      tag = i % 16 === 0 ? "CORRUPT-HARDWARE-ERR" : "INVALID-TAG-XYZ";
    }
    
    // Generate response time (80ms to 240ms base, with periodic focus latency/network delay)
    // Create a predictable wave with some noise to look realistic on a line chart
    const baseTime = 110 + (Math.sin(i / 3) * 40) + (i % 5 === 0 ? 80 : 0);
    const responseTime = Math.round(Math.max(75, Math.min(420, baseTime + (i % 7) * 15)));
    
    const scanTime = now - (i * 3 * 60000); // 3 minutes intervals
    const d = new Date(scanTime);
    const pad = (n: number) => n.toString().padStart(2, '0');
    const timestamp = `${pad(d.getHours())}:${pad(d.getMinutes())} ${d.getHours() >= 12 ? 'PM' : 'AM'}`;
    
    list.push({
      id: `seed-${i}`,
      tag,
      type,
      timestamp,
      dateTime: scanTime,
      status,
      responseTime
    });
  }
  return list;
};

