  useEffect(() => {
    const playBeep = () => {
      try {
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        if (!AudioContextClass) return;
        const audioCtx = new AudioContextClass();
        const oscillator = audioCtx.createOscillator();
        const gainNode = audioCtx.createGain();

        oscillator.connect(gainNode);
        gainNode.connect(audioCtx.destination);

        oscillator.type = "sine";
        oscillator.frequency.setValueAtTime(880, audioCtx.currentTime); // 880 Hz beep

        gainNode.gain.setValueAtTime(0, audioCtx.currentTime);
        gainNode.gain.linearRampToValueAtTime(0.15, audioCtx.currentTime + 0.01);
        gainNode.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + 0.15);

        oscillator.start(audioCtx.currentTime);
        oscillator.stop(audioCtx.currentTime + 0.15);
      } catch (e) {
        console.warn("Audio feedback play failed:", e);
      }
    };

    const handleQrScanEvent = (e: any) => {
      if (e.detail) {
        setLastScan(e.detail);
        setTotalScansInSession(prev => prev + 1);
        if (e.detail.status === "VERIFIED") {
          playBeep();
        }
        setScanHistory(prev => {
          const newScan = {
            id: e.detail.id || `SCAN-${Date.now()}-${Math.floor(Math.random() * 1000)}`,
            tag: e.detail.tag,
            type: e.detail.type,
            timestamp: e.detail.timestamp,
            dateTime: e.detail.dateTime || Date.now(),
            status: e.detail.status,
            responseTime: e.detail.responseTime || (80 + Math.floor(Math.random() * 150))
          };
          return [newScan, ...prev].slice(0, 100);
        });
      }
    };
    window.addEventListener("moka-qr-scan", handleQrScanEvent);
    return () => {
      window.removeEventListener("moka-qr-scan", handleQrScanEvent);
    };
  }, []);

