  const pushFailedScanNotification = (scanEvent: { id: string; tagUid: string; hardwareId: string; station: string; details: string; latencyMs?: number }) => {
    const alertMsg = `[NFC HARDWARE ALERT] Failed Handshake Detected!\n\nEvent ID: ${scanEvent.id}\nTag UID: ${scanEvent.tagUid}\nHardware Reader: ${scanEvent.hardwareId}\nStation: ${scanEvent.station}\nDetails: ${scanEvent.details}\nLatency: ${scanEvent.latencyMs || 315}ms`;

    // 1. Browser Native Notification API (if supported and permitted)
    if ("Notification" in window && Notification.permission === "granted") {
      try {
        new Notification("NFC Scan Error: Failed Handshake", {
          body: `Tag: ${scanEvent.tagUid} | Station: ${scanEvent.station}\nDetails: ${scanEvent.details}`,
          icon: "/favicon.ico"
        });
      } catch (e) {
        console.warn("Native Notification API error:", e);
      }
    }

    // 2. Browser Native Alert Modal Window
    window.alert(alertMsg);
  };

  const handleAlertNoiseFloor = () => {
    const latestEmiPt = rollingEmi60sData.length > 0 ? rollingEmi60sData[rollingEmi60sData.length - 1] : null;
    let currentEmiDbm = latestEmiPt ? latestEmiPt.emiDbm : -52.4;

    if (currentEmiDbm <= -60) {
      handleInjectSimulatedEmiSpike();
      currentEmiDbm = -51.8;
    }

    const now = new Date();
    const timeStr = now.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    const logId = `ALERT_EMI_0x${Math.floor(Math.random() * 899 + 100).toString(16)}`;
    const alertMsg = `EMI Noise Floor (${currentEmiDbm.toFixed(1)} dBm) breached -60.0 dBm threshold! Flagged for direct correlation with next failed NFC handshake attempt.`;

    const newAlertLog = {
      id: logId,
      timestamp: timeStr,
      noiseFloorDbm: currentEmiDbm,
      message: alertMsg
    };

    setEmiNoiseAlertLogs(prev => [newAlertLog, ...prev.slice(0, 4)]);
    setPendingEmiNoiseAlert({
      active: true,
      noiseFloorDbm: currentEmiDbm,
      timestamp: timeStr,
      logId: logId
    });

    showToast(
      lang === "ar"
        ? `تم تسجيل حدث النظام: قاع الضوضاء (${currentEmiDbm.toFixed(1)} dBm > -60dBm)! سيتم ربطه بحدث الفشل القادم.`
        : `System Event Logged: EMI Noise Floor (${currentEmiDbm.toFixed(1)} dBm > -60dBm). Flagged for direct correlation with next failed NFC handshake attempt.`,
      "warning"
    );
  };

  const handleTriggerSimulatedFailedScan = () => {
    const now = new Date();
    const timeStr = now.toISOString().replace("T", " ").slice(0, 19) + " UTC";
    const randomTag = `MOKA-FAIL-${Math.floor(10000 + Math.random() * 90000)}`;
    const evtId = `HW-EVT-FAIL-${Math.floor(100 + Math.random() * 900)}`;

    let detailsStr = "ECDSA Signature Mismatch / Cryptographic Handshake Failed / Fraud Flagged";
    let correlatedDbm: number | undefined = undefined;

    if (pendingEmiNoiseAlert && pendingEmiNoiseAlert.active) {
      correlatedDbm = pendingEmiNoiseAlert.noiseFloorDbm;
      detailsStr += ` [CORRELATED EMI NOISE SPIKE: ${pendingEmiNoiseAlert.noiseFloorDbm.toFixed(1)} dBm > -60dBm THRESHOLD BREACH]`;

      const targetLogId = pendingEmiNoiseAlert.logId;
      setEmiNoiseAlertLogs(prev => prev.map(log => {
        if (log.id === targetLogId) {
          return {
            ...log,
            message: `EMI Noise Floor (${log.noiseFloorDbm.toFixed(1)} dBm) breached -60dBm threshold. Correlated directly with Failed Handshake ${evtId}.`,
            correlatedHandshakeId: evtId
          };
        }
        return log;
      }));

      showToast(
        lang === "ar"
          ? `تم ربط حدث قاع الضوضاء EMI (${pendingEmiNoiseAlert.noiseFloorDbm.toFixed(1)} dBm) مباشرة بمصافحة NFC الفاشلة ${evtId}!`
          : `EMI Noise Floor Event (${pendingEmiNoiseAlert.noiseFloorDbm.toFixed(1)} dBm) correlated directly with Failed NFC Handshake ${evtId}!`,
        "error"
      );

      setPendingEmiNoiseAlert(null);
    }

    const failedScanEvent = {
      id: evtId,
      timestamp: timeStr,
      tagUid: randomTag,
      hardwareId: "HW-RDR-07C (ACR122U Diagnostic Reader)",
      station: "Aramco Station - Olaya Dist.",
      status: "Failed",
      details: detailsStr,
      rssi: "-82 dBm",
      latencyMs: 315,
      correlatedEmiDbm: correlatedDbm
    };

    setNfcHardwareScanEventsList(prev => [failedScanEvent, ...prev]);

    // Automatically save waveform diagnostic snapshot to local storage buffer if toggle is enabled
    if (autoSaveWaveformOnFailedHandshake && saveWaveformDiagnosticBufferRef.current) {
      saveWaveformDiagnosticBufferRef.current({
        handshakeId: evtId,
        timestamp: timeStr,
        tagUid: randomTag,
        errorCode: "ERR_FAILED_HANDSHAKE_ECDSA_MISMATCH",
        reason: detailsStr,
        hardwareReader: failedScanEvent.hardwareId
      });
    }

    if (scanErrorNotificationsEnabled) {
      pushFailedScanNotification(failedScanEvent);
    } else {
      showToast(
        lang === "ar"
          ? `تم تسجيل خطأ المصافحة (${evtId}) - قم بتفعيل "تنبيهات أخطاء المسح" لإطلاق التنبيه التلقائي`
          : `Recorded Failed Handshake (${evtId}). Enable Scan Error Alerts to receive automatic browser notifications.`,
        "warning"
      );
    }
  };

  const handleRunWaveformAnalysis = () => {
    setIsAnalyzingWaveform(true);
    const now = new Date();
    const timeStr = now.toLocaleTimeString();
    const artId = `WF-ART-${Math.floor(1000 + Math.random() * 9000)}`;
    const targetEvtId = selectedTroubleshootingHandshake?.id || (nfcHardwareScanEventsList.length > 0 ? nfcHardwareScanEventsList[0].id : "HW-EVT-104");

    const currentJitter = selectedTroubleshootingHandshake ? 35.1 : 28.4;
    const peakDbm = -45.0 + (Math.random() * 4 - 2);
    const thd = Number((2.2 + Math.random() * 1.5).toFixed(2));
    const harmonicSpur = Number((-68.0 + Math.random() * 8).toFixed(1));
    const freqMHz = Number((rfCarrierFreqMHz + (currentJitter / 100000)).toFixed(6));

    const fftPoints = [
      { freqOffsetKhz: -1000, dbm: Number((peakDbm - 42).toFixed(1)) },
      { freqOffsetKhz: -840, dbm: Number((peakDbm - 38).toFixed(1)) },
      { freqOffsetKhz: -420, dbm: Number((peakDbm - 24).toFixed(1)) },
      { freqOffsetKhz: -210, dbm: Number((peakDbm - 12).toFixed(1)) },
      { freqOffsetKhz: 0, dbm: Number(peakDbm.toFixed(1)) },
      { freqOffsetKhz: 210, dbm: Number((peakDbm - 11).toFixed(1)) },
      { freqOffsetKhz: 420, dbm: Number((peakDbm - 26).toFixed(1)) },
      { freqOffsetKhz: 840, dbm: Number((peakDbm - 36).toFixed(1)) },
      { freqOffsetKhz: 1000, dbm: Number((peakDbm - 45).toFixed(1)) },
    ];

    const timeSamples = Array.from({ length: 11 }).map((_, i) => {
      const tUs = -25 + i * 5;
      const angle = (i / 10) * Math.PI * 2;
      return {
        timeUs: tUs,
        mv: Math.round(Math.sin(angle) * 450 + (Math.random() * 30 - 15))
      };
    });

    const newArtifact = {
      id: artId,
      timestamp: timeStr,
      handshakeId: targetEvtId,
      carrierFreqMHz: freqMHz,
      centerFreqMHz: `${freqMHz} MHz`,
      spectralPeakDbm: Number(peakDbm.toFixed(1)),
      thdPercent: thd,
      harmonicSpurDbm: harmonicSpur,
      jitterPpm: currentJitter,
      snrDb: Number((22.4 - Math.random() * 5).toFixed(1)),
      bandwidthKhz: 420,
      fftSpectrumPoints: fftPoints,
      timeDomainSamples: timeSamples,
      status: "ANALYZED" as const,
      diagnosticNote: `High-resolution RF carrier pulse waveform snapshot stored. Frequency spectral analysis reveals ${thd}% THD distortion and ${currentJitter} ppm phase jitter peak during failed handshake ${targetEvtId}.`
    };

    setTimeout(() => {
      setWaveformAnalysisArtifacts(prev => [newArtifact, ...prev]);
      setSelectedWaveformArtifact(newArtifact);
      setIsAnalyzingWaveform(false);
      showToast(
        lang === "ar"
          ? `تم إجراء تحليل شكل الموجة وحفظ المستند التشخيصي (${artId}) بنجاح!`
          : `Waveform spectral analysis completed! Diagnostic artifact stored as ${artId}.`,
        "success"
      );
    }, 500);
  };

  const stressTestBatteryPercent = useMemo(() => {
    const basePercent = nfcPingResult ? nfcPingResult.batteryLevelPercent : 94;
    if (isHardwareStressTestRunning) {
      if (stressTestRfState === "RF_ON") {
        return Math.max(5, basePercent - 4);
      } else {
        return Math.max(5, basePercent - Math.min(2, Math.floor(stressTestCurrentCycle * 0.2)));
      }
    }
    return basePercent;
  }, [nfcPingResult, isHardwareStressTestRunning, stressTestRfState, stressTestCurrentCycle]);

  // Rolling 60-Second EMI Intensity & Voltage Sag Correlation Stream
  const [isEmiStreamingPaused, setIsEmiStreamingPaused] = useState<boolean>(false);
  const [rollingEmi60sData, setRollingEmi60sData] = useState<Array<{
    secondOffset: number; // -60 to 0
    timeLabel: string;
    emiDbm: number; // -95 to -40 dBm
    emiIntensityPercent: number; // 0 to 100%
    emiMvM: number; // Field strength in mV/m
    voltageSagVolts: number; // 0.00V to 0.45V
    railVoltage: number; // 3.85V to 3.40V
    isHighNoiseEvent: boolean;
    emiEventName: string;
    correlationScore: number;
  }>>(() => {
    // Initial 60-second window dataset
    const initialPoints = [];
    for (let i = 59; i >= 0; i--) {
      const secOffset = -i;
      const isBurst1 = i >= 42 && i <= 46;
      const isBurst2 = i >= 18 && i <= 22;
      const isBurst3 = i >= 4 && i <= 6;

      let emiDbm = -85 + Math.sin(i * 0.4) * 4;
      let emiMvM = 4.2 + Math.sin(i * 0.4) * 1.5;
      let sagVolts = 0.04 + Math.random() * 0.03;
      let emiEvent = "Quiet Ambient Floor";

      if (isBurst1) {
        emiDbm = -48 + (Math.random() * 6 - 3);
        emiMvM = 135 + (Math.random() * 25);
        sagVolts = 0.35 + (Math.random() * 0.06);
        emiEvent = "Switch-Mode Buck Regulator Ripple (450kHz)";
      } else if (isBurst2) {
        emiDbm = -52 + (Math.random() * 5 - 2.5);
        emiMvM = 110 + (Math.random() * 20);
        sagVolts = 0.31 + (Math.random() * 0.05);
        emiEvent = "Motor Coil Switching Transients EMI Burst";
      } else if (isBurst3) {
        emiDbm = -58 + Math.random() * 4;
        emiMvM = 82 + Math.random() * 15;
        sagVolts = 0.22 + Math.random() * 0.04;
        emiEvent = "Wi-Fi 2.4GHz Beacon Transmission Spike";
      }

      const emiPct = Math.min(100, Math.max(5, Math.round(((emiDbm + 100) / 60) * 100)));
      const railV = +(3.85 - sagVolts).toFixed(2);
      const isHighNoise = emiDbm > -65 || sagVolts > 0.20;
      const corrScore = isHighNoise ? Math.round(88 + Math.random() * 10) : Math.round(15 + Math.random() * 20);

      initialPoints.push({
        secondOffset: secOffset,
        timeLabel: secOffset === 0 ? "0s" : `${secOffset}s`,
        emiDbm: +emiDbm.toFixed(1),
        emiIntensityPercent: emiPct,
        emiMvM: +emiMvM.toFixed(1),
        voltageSagVolts: +sagVolts.toFixed(2),
        railVoltage: railV,
        isHighNoiseEvent: isHighNoise,
        emiEventName: emiEvent,
        correlationScore: corrScore
      });
    }
    return initialPoints;
  });

  // Ticker Effect: Continuously shifts rolling 60-second EMI window
  useEffect(() => {
    if (isEmiStreamingPaused) return;

    const ticker = setInterval(() => {
      setRollingEmi60sData((prevData) => {
        if (!prevData || prevData.length === 0) return prevData;

        const isRandomBurst = Math.random() < 0.08;
        let nextDbm = -84 + (Math.random() * 8 - 4);
        let nextMvM = 5.0 + (Math.random() * 3 - 1.5);
        let nextSag = 0.05 + (Math.random() * 0.03);
        let eventName = "Ambient Noise Floor";

        if (isHardwareStressTestRunning) {
          if (stressTestRfState === "RF_ON") {
            nextDbm = -51 + (Math.random() * 8 - 4);
            nextMvM = 120 + (Math.random() * 30);
            nextSag = 0.33 + (Math.random() * 0.07);
            eventName = "RF Transmitter Transmitter Pulse Burst";
          } else {
            nextDbm = -82 + (Math.random() * 4);
            nextMvM = 6.0 + (Math.random() * 2);
            nextSag = 0.02 + (Math.random() * 0.02);
            eventName = "RF Transmitter Idle Rail";
          }
        } else if (isRandomBurst) {
          nextDbm = -49 + (Math.random() * 6);
          nextMvM = 128 + (Math.random() * 25);
          nextSag = 0.34 + (Math.random() * 0.06);
          eventName = "Spurious Switch-Mode Power Converter EMI Burst";
        }

        const emiPct = Math.min(100, Math.max(5, Math.round(((nextDbm + 100) / 60) * 100)));
        const railV = +(3.85 - nextSag).toFixed(2);
        const isHighNoise = nextDbm > -65 || nextSag > 0.20;
        const corrScore = isHighNoise ? Math.round(90 + Math.random() * 8) : Math.round(18 + Math.random() * 20);

        const shifted = prevData.slice(1).map((pt, idx) => {
          const newSec = -(59 - idx);
          return {
            ...pt,
            secondOffset: newSec,
            timeLabel: `${newSec}s`
          };
        });

        shifted.push({
          secondOffset: 0,
          timeLabel: "0s",
          emiDbm: +nextDbm.toFixed(1),
          emiIntensityPercent: emiPct,
          emiMvM: +nextMvM.toFixed(1),
          voltageSagVolts: +nextSag.toFixed(2),
          railVoltage: railV,
          isHighNoiseEvent: isHighNoise,
          emiEventName: eventName,
          correlationScore: corrScore
        });

        return shifted;
      });
    }, 1000);

    return () => clearInterval(ticker);
  }, [isEmiStreamingPaused, isHardwareStressTestRunning, stressTestRfState]);

  // Helper to inject manual simulated EMI spike
  const handleInjectSimulatedEmiSpike = () => {
    setRollingEmi60sData((prev) => {
      if (!prev || prev.length === 0) return prev;
      const copy = [...prev];
      const lastIdx = copy.length - 1;
      const spikeDbm = -44.2;
      const spikeMvM = 162.0;
      const spikeSag = 0.39;

      copy[lastIdx] = {
        ...copy[lastIdx],
        emiDbm: spikeDbm,
        emiIntensityPercent: 95,
        emiMvM: spikeMvM,
        voltageSagVolts: spikeSag,
        railVoltage: 3.46,
        isHighNoiseEvent: true,
        emiEventName: "MANUAL TRIGGER: High-Intensity EMI Burst (162 mV/m)",
        correlationScore: 99
      };
      return copy;
    });
  };

  const handleRunHardwareStressTest = () => {
    if (isHardwareStressTestRunning) return;
    setIsHardwareStressTestRunning(true);
    setStressTestCurrentCycle(0);
    setStressTestLog([]);
    setHardwareStressTestResult(null);

    let cycleCount = 0;
    const initialVoltage = nfcPingResult ? nfcPingResult.voltageVolts : 3.85;
    const logAcc: Array<{
      cycle: number;
      rfState: "RF_ON" | "RF_OFF";
      voltageVolts: number;
      sagVolts: number;
      status: "STABLE" | "SAG_DETECTED";
      timestampMs: string;
      startOffsetMs: string;
      latencyMs: number;
      carrierFreqMHz?: number;
      autoCalibrated?: boolean;
      noiseFloorDbm?: number;
      emiEvent?: string;
      interferenceLevel?: "LOW" | "MODERATE" | "HIGH" | "CRITICAL";
    }> = [];

    const interval = setInterval(() => {
      cycleCount++;
      setStressTestCurrentCycle(cycleCount);
      const rfState: "RF_ON" | "RF_OFF" = cycleCount % 2 === 1 ? "RF_ON" : "RF_OFF";
      setStressTestRfState(rfState);

      // Simulate sag during RF_ON pulse
      const isLowPwr = nfcPingResult ? (nfcPingResult.batteryLevelPercent < 20 || nfcPingResult.powerState === "LOW_BATTERY_CRITICAL") : false;
      const baseSag = rfState === "RF_ON" ? (isLowPwr ? 0.42 + Math.random() * 0.15 : 0.08 + Math.random() * 0.12) : 0;
      const currentVoltage = +(initialVoltage - baseSag).toFixed(2);
      const sagVal = +baseSag.toFixed(2);
      const isSag = sagVal > 0.30;

      // Noise floor and EMI event correlation logic
      const noiseFloor = isSag
        ? +(-58 + Math.random() * 10).toFixed(1)
        : baseSag > 0.10
        ? +(-78 + Math.random() * 6).toFixed(1)
        : +(-88 + Math.random() * 4).toFixed(1);

      const emiEv = isSag
        ? (Math.random() > 0.5 ? "Switch-Mode Regulator Ripple (450 kHz)" : "Motor Driver Transients EMI Burst")
        : baseSag > 0.10
        ? "Wi-Fi 2.4GHz Beacon Bleed"
        : "Quiet Ambient Floor";

      const interfLevel: "LOW" | "MODERATE" | "HIGH" | "CRITICAL" = isSag
        ? "CRITICAL"
        : baseSag > 0.10
        ? "MODERATE"
        : "LOW";

      // Auto-Calibration Sequence for RF carrier frequency when sag > 0.30V
      let currentCarrier = rfCarrierFreqMHz;
      let wasCalibrated = false;

      if (isSag) {
        // Shift within 13.56 MHz +/- 0.5% (13.492 MHz to 13.628 MHz)
        const shiftOffsetMHz = +((Math.random() > 0.5 ? 1 : -1) * (0.018 + Math.random() * 0.045)).toFixed(3);
        const tunedFreq = +(13.560 + shiftOffsetMHz).toFixed(3);
        const deltaPct = `${shiftOffsetMHz >= 0 ? "+" : ""}${((shiftOffsetMHz / 13.560) * 100).toFixed(2)}%`;
        currentCarrier = tunedFreq;
        wasCalibrated = true;

        setRfCarrierFreqMHz(tunedFreq);
        setRfAutoCalibrationStatus(prev => ({
          active: true,
          calibratedCount: prev.calibratedCount + 1,
          lastShiftMHz: tunedFreq,
          lastDeltaPercent: deltaPct,
          triggerSagVolts: sagVal,
          resonancePeakPercent: 98.6,
          statusText: `AUTO-CALIBRATION ACTIVATED: Voltage sag ${sagVal}V (>0.30V limit) detected at Cycle #${cycleCount}! Shifted carrier to ${tunedFreq} MHz (${deltaPct}) to align resonance peak.`
        }));
      }

      const now = new Date();
      const timeMsStr = `${now.toTimeString().split(' ')[0]}.${String(now.getMilliseconds()).padStart(3, '0')}`;
      const elapsedMs = (cycleCount - 1) * 250;
      const latencyVal = +(11.5 + Math.random() * 1.5).toFixed(1);

      const newEntry = {
        cycle: cycleCount,
        rfState,
        voltageVolts: currentVoltage,
        sagVolts: sagVal,
        status: isSag ? ("SAG_DETECTED" as const) : ("STABLE" as const),
        timestampMs: timeMsStr,
        startOffsetMs: `+${elapsedMs} ms`,
        latencyMs: latencyVal,
        carrierFreqMHz: currentCarrier,
        autoCalibrated: wasCalibrated,
        noiseFloorDbm: noiseFloor,
        emiEvent: emiEv,
        interferenceLevel: interfLevel
      };
      logAcc.push(newEntry);
      setStressTestLog([...logAcc]);

      if (cycleCount >= 10) {
        clearInterval(interval);
        setIsHardwareStressTestRunning(false);
        setStressTestRfState("RF_OFF");

        const maxSag = Math.max(...logAcc.map(l => l.sagVolts));
        const minVolts = Math.min(...logAcc.map(l => l.voltageVolts));
        const avgVolts = +(logAcc.reduce((acc, curr) => acc + curr.voltageVolts, 0) / logAcc.length).toFixed(2);
        const failedCycles = logAcc.filter(l => l.status === "SAG_DETECTED").length;
        const passedCycles = 10 - failedCycles;

        let health: "STABLE" | "SAG_WARNING" | "CRITICAL_SAG" = "STABLE";
        let rec = "Power rail decoupling capacitors operating within nominal ripple tolerances (<0.20V Vdrop). No voltage collapse observed under 10x RF bursts.";

        if (maxSag > 0.35 || minVolts < 3.20) {
          health = "CRITICAL_SAG";
          rec = "CRITICAL: Voltage sag exceeds 0.35V during RF burst! Power rail decoupling capacitor or LiFePO4 internal resistance degradation detected. High risk of reader reset.";
        } else if (maxSag > 0.20) {
          health = "SAG_WARNING";
          rec = "WARNING: Moderate power rail ripple (0.20V - 0.35V Vdrop). Inspect 100uF bypass capacitors on 3.3V DC rail.";
        }

        const now = new Date();
        const timeStr = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}:${String(now.getSeconds()).padStart(2, "0")}`;

        setHardwareStressTestResult({
          testedAt: timeStr,
          totalCycles: 10,
          passedCycles,
          maxSagVolts: +maxSag.toFixed(2),
          minRailVoltage: +minVolts.toFixed(2),
          powerRailHealth: health,
          recommendation: rec
        });

        // Record session to session history array (keep last 10 sessions)
        setStressTestSessionHistory(prev => {
          const nextSessionNum = prev.length > 0 ? prev[prev.length - 1].sessionNumber + 1 : 1;
          const calculatedRssi = nfcPingResult ? nfcPingResult.rssiDbm : (maxSag > 0.30 ? -68 : -56);
          const calculatedQuality = nfcPingResult ? nfcPingResult.signalQualityPercent : (maxSag > 0.30 ? 74 : 94);
          const calculatedLossDb = +(0.2 + (nextSessionNum * 0.35) + (maxSag * 2.2)).toFixed(1);
          const calculatedVswr = +(1.10 + (maxSag * 0.6) + (nextSessionNum * 0.03)).toFixed(2);

          const newSession = {
            sessionId: `S-${100 + nextSessionNum}`,
            sessionNumber: nextSessionNum,
            timestamp: timeStr,
            avgVoltageVolts: avgVolts,
            maxSagVolts: +maxSag.toFixed(2),
            minRailVoltage: +minVolts.toFixed(2),
            health,
            batteryPercent: stressTestBatteryPercent,
            terminalVoltageDropMv: Math.round(maxSag * 1000),
            rssiDbm: calculatedRssi,
            signalQualityPercent: calculatedQuality,
            antennaLossDb: calculatedLossDb,
            vswrRatio: calculatedVswr
          };
          const updated = [...prev, newSession];
          return updated.slice(-10);
        });

        // Record to long-term forensic log history
        const isoDate = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
        const fullTimeStr = `${isoDate} ${timeStr}`;
        const newHistRecord = {
          id: `HST-${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}-${String(Math.floor(100 + Math.random() * 900))}`,
          timestamp: fullTimeStr,
          durationMs: 2500,
          maxSagVolts: +maxSag.toFixed(2),
          minRailVoltage: +minVolts.toFixed(2),
          avgRailVoltage: +(minVolts + 0.12).toFixed(2),
          totalCycles: 10,
          passedCycles,
          failedCycles,
          powerRailHealth: health,
          status: health === "STABLE" ? ("PASS" as const) : health === "SAG_WARNING" ? ("WARNING" as const) : ("FAIL" as const),
          readerId: nfcPingResult?.hardwareReader || "RDR-NFC-9982",
          batteryPercent: stressTestBatteryPercent,
          peakEmiMvM: +(115 + Math.random() * 35).toFixed(1),
          recommendation: rec
        };
        setHardwareStressTestLogHistory(prev => [newHistRecord, ...prev]);
        setExpandedHistoryLogId(newHistRecord.id);
      }
    }, 250);
  };

  const handleManualRfRecalibration = () => {
    const shiftOffsetMHz = +((Math.random() > 0.5 ? 1 : -1) * (0.015 + Math.random() * 0.042)).toFixed(3);
    const tunedFreq = +(13.560 + shiftOffsetMHz).toFixed(3);
    const deltaPct = `${shiftOffsetMHz >= 0 ? "+" : ""}${((shiftOffsetMHz / 13.560) * 100).toFixed(2)}%`;
    setRfCarrierFreqMHz(tunedFreq);
    setRfAutoCalibrationStatus({
      active: true,
      calibratedCount: rfAutoCalibrationStatus.calibratedCount + 1,
      lastShiftMHz: tunedFreq,
      lastDeltaPercent: deltaPct,
      triggerSagVolts: 0.31,
      resonancePeakPercent: 99.1,
      statusText: `MANUAL RE-CALIBRATION: Shifted RF carrier frequency to ${tunedFreq} MHz (${deltaPct}) across 13.56MHz ±0.5% window for peak antenna tank circuit resonance.`
    });
  };

  const handleResetRfCarrierFreq = () => {
    setRfCarrierFreqMHz(13.560);
    setRfAutoCalibrationStatus({
      active: false,
      calibratedCount: rfAutoCalibrationStatus.calibratedCount,
      lastShiftMHz: 13.560,
      lastDeltaPercent: "0.00%",
      triggerSagVolts: 0,
      resonancePeakPercent: 100,
      statusText: "RF Carrier reset to 13.560 MHz standard (Nominal LC Tank Peak 100%)"
    });
  };

  // Helper Handlers for Hardware Stress Test Forensic Log History & Compliance PDF
  const handleExportStressTestPDF = () => {
    const element = document.getElementById("nfc-hardware-stress-test-pdf-template");
    if (!element) {
      showToast(lang === "ar" ? "تعذر العثور على قالب PDF" : "PDF template not found", "error");
      return;
    }
    
    setIsGeneratingStressTestPDF(true);
    
    const opt: any = {
      margin:       [8, 8, 8, 8],
      filename:     `MOKA_NFC_Hardware_StressTest_Compliance_Report_${new Date().toISOString().slice(0, 10)}.pdf`,
      image:        { type: 'jpeg', quality: 0.98 },
      html2canvas:  { 
        scale: 2.2,
        useCORS: true, 
        letterRendering: true,
        backgroundColor: '#ffffff',
        logging: false
      },
      jsPDF:        { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };
    
    html2pdf()
      .from(element)
      .set(opt)
      .save()
      .then(() => {
        setIsGeneratingStressTestPDF(false);
        showToast(
          lang === "ar"
            ? "تم تصدير تقرير التدقيق كملف PDF بنجاح!"
            : "NFC Hardware Stress Test PDF Compliance Report exported successfully!",
          "success"
        );
      })
      .catch((err: any) => {
        console.error("[ERROR] Stress test PDF export failed:", err);
        setIsGeneratingStressTestPDF(false);
        showToast(lang === "ar" ? "فشل تصدير PDF" : "Failed to export PDF compliance report", "error");
      });
  };

  const handleExportStressTestLogsJson = () => {
    const jsonStr = JSON.stringify(hardwareStressTestLogHistory, null, 2);
    const blob = new Blob([jsonStr], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `nfc-hardware-stress-test-history-${new Date().toISOString().slice(0, 10)}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleExportStressTestLogsCsv = () => {
    const headers = "ID,Timestamp,Duration (ms),Max Sag (V),Min Voltage (V),Cycles,Passed,Failed,Health,Status,Reader ID,Battery (%),Peak EMI (mV/m),Recommendation\n";
    const rows = hardwareStressTestLogHistory.map(r =>
      `"${r.id}","${r.timestamp}",${r.durationMs},${r.maxSagVolts},${r.minRailVoltage},${r.totalCycles},${r.passedCycles},${r.failedCycles},"${r.powerRailHealth}","${r.status}","${r.readerId}",${r.batteryPercent},${r.peakEmiMvM},"${r.recommendation.replace(/"/g, '""')}"`
    ).join("\n");
    const blob = new Blob([headers + rows], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `nfc-hardware-stress-test-history-${new Date().toISOString().slice(0, 10)}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleExportHardwareStressTestCsv = () => {
    try {
      const now = new Date();
      const dateStr = now.toISOString().slice(0, 10);
      const timeStr = now.toTimeString().split(" ")[0];

      const passedCount = hardwareStressTestResult?.passedCycles ?? stressTestLog.filter(l => l.status === "STABLE").length;
      const totalCycles = 10;
      const failedCount = totalCycles - passedCount;
      const passPercentage = ((passedCount / totalCycles) * 100).toFixed(0);
      const maxSag = hardwareStressTestResult?.maxSagVolts ?? (stressTestLog.length ? Math.max(...stressTestLog.map(l => l.sagVolts)) : 0.13);
      const minRail = hardwareStressTestResult?.minRailVoltage ?? (stressTestLog.length ? Math.min(...stressTestLog.map(l => l.voltageVolts)) : 3.72);
      const avgVoltage = (hardwareStressTestResult as any)?.avgVoltageVolts ?? 3.82;
      const health = hardwareStressTestResult?.powerRailHealth ?? (passedCount >= 9 ? "STABLE" : "SAG_WARNING");
      const overallStatus = passedCount >= 9 ? "PASS" : "FAIL";

      let csv = "\ufeff"; // UTF-8 BOM for Excel compatibility
      csv += "=== MOKA NFC HARDWARE STRESS TEST AUDIT COMPLIANCE REPORT ===\n";
      csv += `Report Date,${dateStr} ${timeStr}\n`;
      csv += `NFC Hardware Reader ID,${nfcPingResult?.hardwareReader || "RDR-NFC-9982"}\n`;
      csv += `Overall Session Status,${overallStatus}\n`;
      csv += `Power Rail Health Classification,${health}\n`;
      csv += `Total RF Burst Cycles Triggered,${totalCycles}\n`;
      csv += `Passed Cycles (No Brownout Reset),${passedCount} / ${totalCycles} (${passPercentage}%)\n`;
      csv += `Failed Cycles (Voltage Sag > 0.20V),${failedCount} / ${totalCycles}\n`;
      csv += `Maximum Rail Voltage Sag (Peak Vdrop),-${maxSag.toFixed(2)} V\n`;
      csv += `Minimum Rail Voltage Recorded,${minRail.toFixed(2)} V\n`;
      csv += `Average Rail Voltage,${avgVoltage.toFixed(2)} V\n`;
      csv += `Battery State of Charge (SoC),${stressTestBatteryPercent}%\n`;
      csv += "\n";
      csv += "=== CYCLE-BY-CYCLE POWER RAIL VOLTAGE DROP DATA LOG ===\n";
      csv += "Cycle #,Timestamp,RF State,Rail Voltage (V),Voltage Sag (V),Carrier Frequency (MHz),EMI Noise Event,Cycle Status\n";

      if (stressTestLog && stressTestLog.length > 0) {
        stressTestLog.forEach(log => {
          csv += `Cycle #${log.cycle},"${log.timestampMs || timeStr}","${log.rfState}",${log.voltageVolts.toFixed(2)},-${log.sagVolts.toFixed(2)},${log.carrierFreqMHz ? log.carrierFreqMHz.toFixed(3) : "13.560"},"${(log.emiEvent || "Quiet Ambient Floor").replace(/"/g, '""')}","${log.status === "STABLE" ? "PASS" : "SAG FAIL"}"\n`;
        });
      } else {
        for (let i = 1; i <= 10; i++) {
          const isRfOn = i % 2 !== 0;
          const v = isRfOn ? 3.72 : 3.85;
          const sag = isRfOn ? 0.13 : 0.02;
          csv += `Cycle #${i},"${timeStr}",${isRfOn ? "RF_ON" : "RF_OFF"},${v.toFixed(2)},-${sag.toFixed(2)},13.560,"${isRfOn ? "RF Transmit Pulse Peak" : "Quiet Ambient Floor"}","PASS"\n`;
        }
      }

      csv += "\n";
      csv += "=== COMPLIANCE DISCLAIMER & DIGEST ===\n";
      csv += "Compliance Standard,FCC Class B / ISO-14443A / ZATCA Level 2 Hardware Specs\n";
      csv += `Integrity Checksum Digest,${Date.now().toString(16)}-nfc-stress-compliance-audit-digest\n`;

      const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `nfc-hardware-stress-test-cycles-${dateStr}.csv`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      showToast(
        lang === "ar"
          ? "تم تصدير دورات اختبار الإجهاد وسجلات الجلسة كملف CSV بنجاح!"
          : "Hardware stress test cycle logs & pass/fail stats exported as CSV!",
        "success"
      );
    } catch (err) {
      console.error("Export CSV error:", err);
      showToast(lang === "ar" ? "فشل تصدير ملف CSV" : "Failed to export CSV file", "error");
    }
  };

