  const handleInjectSimulatedPastTestLog = () => {
    const now = new Date();
    const isoDate = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    const fullTimeStr = `${isoDate} ${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}:${String(now.getSeconds()).padStart(2, "0")}`;
    const randomSag = +(0.08 + Math.random() * 0.35).toFixed(2);
    const isCritical = randomSag > 0.35;
    const isWarn = randomSag > 0.20 && !isCritical;

    const mockEntry = {
      id: `HST-${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(now.getDate()).padStart(2, '0')}-${String(Math.floor(100 + Math.random() * 900))}`,
      timestamp: fullTimeStr,
      durationMs: 2500,
      maxSagVolts: randomSag,
      minRailVoltage: +(3.85 - randomSag).toFixed(2),
      avgRailVoltage: +(3.85 - randomSag + 0.12).toFixed(2),
      totalCycles: 10,
      passedCycles: isCritical ? 6 : isWarn ? 8 : 10,
      failedCycles: isCritical ? 4 : isWarn ? 2 : 0,
      powerRailHealth: isCritical ? ("CRITICAL_SAG" as const) : isWarn ? ("SAG_WARNING" as const) : ("STABLE" as const),
      status: isCritical ? ("FAIL" as const) : isWarn ? ("WARNING" as const) : ("PASS" as const),
      readerId: nfcPingResult?.hardwareReader || "RDR-NFC-9982",
      batteryPercent: Math.round(40 + Math.random() * 55),
      peakEmiMvM: +(105 + Math.random() * 55).toFixed(1),
      recommendation: isCritical
        ? "CRITICAL: Severe power rail sag >0.35V observed during test pulse! Inspect power decoupling network."
        : isWarn
        ? "WARNING: Ripple voltage (0.20V - 0.35V Vdrop) observed. Check 100uF bypass cap."
        : "Power rail decoupling capacitors operating within nominal ripple tolerances (<0.20V Vdrop)."
    };
    setHardwareStressTestLogHistory(prev => [mockEntry, ...prev]);
    setExpandedHistoryLogId(mockEntry.id);
  };

